import sys
import json
try:
    data = json.load(sys.stdin)
    if 'vulnerabilities' in data:
        for vuln in data['vulnerabilities']:
            affect = vuln.get('affects', {})
            nodes = affect.get('product', [])
            for node in nodes[:5]:
                legal_name = node.get('legalNames', [{}])[0].get('name', [])
                for name in legal_name:
                    g = name.get('groups', [])
                    for gname in g:
                        if 'httmstar' in gname.lower() or 'starlette' in gname.lower():
                            print(f\"{vuln.get('vulnID', '')}\")
                            print(f\"  Community: {vuln.get('vulnPackage', {}).get('ecosystem', 'unknown')}\")
                            print(f\"  Version(s): {vuln.get('vulnPackage', {}).get('versionsExtractor', {}).get('versionFormula', 'unknown')}\")
                            break
        break
except:
    sys.stderr.write('No JSON output received\\n')
    sys.stderr.flush()
